Your expense tracker is below: add an item, pick a category, and it keeps a running total for the month. Entries are not saved, so they clear when you close the page.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
h1{font-size:18px;margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:6px}
input{flex:1;min-width:110px}
button{background:#2b6cb0;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#c53030;padding:2px 8px}
.total{font-size:24px;font-weight:600}
.bar{height:8px;background:#e2e8f0;border-radius:4px;overflow:hidden;margin:2px 0 8px}
.bar div{height:100%;background:#2b6cb0}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.small{font-size:12px;color:#666}
.over{color:#c53030}
</style></head><body>
<h1>Monthly expenses</h1>
<div class="card">
<div class="row">
<input id="d" placeholder="What for?">
<input id="a" type="number" min="0" placeholder="Amount (₹)">
<select id="c"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Other</option></select>
<button id="add">Add</button>
</div>
</div>
<div class="card">
<div class="small">Total this month</div>
<div class="total" id="t">₹0</div>
<div class="row" style="margin-top:8px;align-items:center">
<span class="small">Budget (₹)</span><input id="b" type="number" min="0" placeholder="Optional">
</div>
<div class="small" id="bs"></div>
</div>
<div class="card"><div class="small" style="margin-bottom:6px">By category</div><div id="cats"></div></div>
<div class="card"><div class="small" style="margin-bottom:6px">Entries</div><div id="list"></div></div>
<script>
var items=[];
var $=function(i){return document.getElementById(i)};
function inr(n){return "₹"+Number(n).toLocaleString("en-IN")}
function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.a;by[e.c]=(by[e.c]||0)+e.a});
  $("t").textContent=inr(total);
  var b=Number($("b").value);
  var bs=$("bs");
  if(b>0){
    var left=b-total;
    bs.textContent=left>=0?inr(left)+" left of your budget":inr(-left)+" over your budget";
    bs.className="small"+(left<0?" over":"");
  }else{bs.textContent="";}
  var cats=$("cats");cats.textContent="";
  Object.keys(by).forEach(function(k){
    var w=document.createElement("div");
    var l=document.createElement("div");l.className="small";
    l.textContent=k+": "+inr(by[k]);
    var bar=document.createElement("div");bar.className="bar";
    var f=document.createElement("div");f.style.width=(total?by[k]/total*100:0)+"%";
    bar.appendChild(f);w.appendChild(l);w.appendChild(bar);cats.appendChild(w);
  });
  var list=$("list");list.textContent="";
  items.forEach(function(e,i){
    var r=document.createElement("div");r.className="item";
    var s=document.createElement("span");s.textContent=e.d+" ("+e.c+")";
    var m=document.createElement("span");m.textContent=inr(e.a)+" ";
    var x=document.createElement("button");x.className="x";x.textContent="Delete";
    x.onclick=function(){items.splice(i,1);render()};
    m.appendChild(x);r.appendChild(s);r.appendChild(m);list.appendChild(r);
  });
}
$("add").onclick=function(){
  var a=Number($("a").value);
  if(!(a>0))return;
  items.push({d:$("d").value||"Expense",a:a,c:$("c").value});
  $("d").value="";$("a").value="";
  render();
};
$("b").oninput=render;
render();
</script>
</body></html>
```

